import { Module } from '@nestjs/common';
import { LlmModule } from '../llm/llm.module.js';
import { MetricsModule } from '../metrics/metrics.module.js';
import { rootConfigModule, rootDatabaseModule } from '../root.modules.js';
import { EvalRunner } from './eval-runner.service.js';
import { EvalRunsModule } from './eval-runs.module.js';

/**
 * What `npm run eval` boots: config, database, the LLM stack and the runner,
 * as a standalone application context (no HTTP server). Not AppModule: that
 * would also start the stuck-quiz sweep, which could mark a quiz being
 * generated by a running API as interrupted.
 */
@Module({
  // MetricsModule provides LlmMetrics, which LlmService records into.
  imports: [
    rootConfigModule,
    rootDatabaseModule,
    MetricsModule,
    LlmModule,
    EvalRunsModule,
  ],
  providers: [EvalRunner],
})
export class EvalCliModule {}

/** What eval:compare and eval:sample boot: only config and the database. */
@Module({
  imports: [rootConfigModule, rootDatabaseModule, EvalRunsModule],
})
export class EvalRunsCliModule {}
